"""Fuente única de ejercicios para notas y notebooks."""
from contenido import clean
EXERCISES = []
N, A = "Núcleo", "Ampliación"
P,C,F,W,T = "Predice la salida","Corrige el error","Completa el código","Escribe desde cero","Reto Tierra"
def ex(d, sec, stars, minutes, kind, title, prompt, setup, solution, check, hint, why):
    seq=1+sum(e["day"]==d for e in EXERCISES)
    EXERCISES.append(dict(day=d,section=sec,stars=stars,minutes=minutes,kind=kind,
        id=f"P{d}.E-{seq:02}",title=title,prompt=prompt,setup=clean(setup),solution=clean(solution),
        check=f'assert ({check}), "{title}: revisa valores, unidades y forma"',hint=hint,why=why))

ex(1,N,1,5,P,"Cociente y resto","Predice 25 // 12 y 25 % 12; guarda cociente y resto.","","cociente=25//12\nresto=25%12","cociente==2 and resto==1","Forma grupos de doce.","Dos grupos completos y una unidad sobrante.")
ex(1,N,1,5,C,"Texto de temperatura","El código erróneo sería kelvin = texto + 273.15. Convierte el texto simulado.","texto='14.0'","kelvin=float(texto)+273.15","abs(kelvin-287.15)<1e-10","Usa float.","Texto y número no se suman directamente.")
ex(1,N,1,5,F,"Tasa por década","Convierte la tasa simulada en decada.","tasa=0.03","decada=tasa*10","abs(decada-0.3)<1e-10","Diez años por década.","La unidad de una tasa cambia con su escala temporal.")
ex(1,N,1,5,P,"Condición de calidad","Predice disponible and valor > 0; guarda resultado.","disponible=True\nvalor=-0.2","resultado=disponible and valor>0","resultado==False","Ambas condiciones deben cumplirse.","El dato existe pero no es positivo.")
ex(1,N,1,5,P,"Retorno invisible","Llama solo_muestra(14.0) y guarda su retorno en resultado.","def solo_muestra(t):\n    print(t)","resultado=solo_muestra(14.0)","resultado==None","Mostrar no es devolver.","Sin return la función devuelve None.")
ex(1,N,2,10,C,"Contador reiniciado","Corrige el diseño que inicia n dentro del for. Cuenta positivos simulados.","datos=[-0.2,0.0,0.1,0.3]","n=0\nfor v in datos:\n    if v>0:\n        n+=1","n==2","Inicializa antes del bucle.","Cero no es positivo.")
ex(1,N,2,10,F,"Salida del while","Suma 0,1,2,3 en total usando while; termina con i=4.","i=0\ntotal=0","while i<4:\n    total+=i\n    i+=1","i==4 and total==6","Actualiza el contador.","La condición se revisa antes de cada vuelta.")
ex(1,N,2,10,W,"Máximo con negativos","Busca mayor a mano sin max.","datos=[-0.8,-0.2,-0.5]","mayor=None\nfor v in datos:\n    if mayor==None or v>mayor:\n        mayor=v","mayor==-0.2","No inicialices en cero.","Cero no pertenece a esta serie simulada.")
ex(1,N,2,10,W,"Conversión reutilizable","Define c_a_k(t) con docstring y return.","",'def c_a_k(t):\n    """Temperatura absoluta de °C a K."""\n    return t+273.15',"abs(c_a_k(0)-273.15)<1e-10 and abs(c_a_k(-10)-263.15)<1e-10","Usa el parámetro t.","Dos entradas comprueban que no devolviste una constante.")
ex(1,N,2,10,C,"Ámbito local","Repara el diseño que lee una variable local fuera: convertir(t) debe devolver °C y K; desempaqueta grados,kelvin.","temperatura=12.0","def convertir(t):\n    return t,t+273.15\ngrados,kelvin=convertir(temperatura)","grados==12 and abs(kelvin-285.15)<1e-10","Devuelve dos valores.","El desempaquetado recoge ambos resultados.")
ex(1,N,2,10,W,"Referencia configurable","Define anomalia(serie,base=14.0) que devuelva una lista nueva.","","def anomalia(serie,base=14.0):\n    salida=[]\n    for v in serie:\n        salida.append(v-base)\n    return salida","anomalia([14,15])==[0,1] and anomalia([12,13],base=12)==[0,1]","Añade diferencias con append.","La referencia es parte del contrato.")
ex(1,N,3,20,T,"Años sobre la referencia","Usa serie_anual de P.D: 24 años desde 2000. Cuenta en positivos valores sobre 14.2; exige v-14.2>1e-9.","datos=serie_anual()","positivos=0\nfor v in datos:\n    if v-14.2>1e-9:\n        positivos+=1","positivos==13","Cuenta de 2011 a 2023.","La tolerancia evita confundir igualdad decimal con exceso.")
ex(1,N,3,20,T,"Integración núcleo P1","Calcula suma,n,mayor y media con un bucle sobre P.D; etiqueta positiva si media>14.","datos=serie_anual()","suma=0.0\nn=0\nmayor=None\nfor v in datos:\n    suma+=v\n    n+=1\n    if mayor==None or v>mayor:\n        mayor=v\nmedia=suma/n\nif media>14:\n    etiqueta='positiva'\nelse:\n    etiqueta='no positiva'","n==24 and abs(media-14.23)<1e-10 and abs(mayor-14.46)<1e-10 and etiqueta=='positiva'","Combina acumuladores y decisión.","Los resultados integran las tres notas.")
ex(1,A,2,10,P,"Retorno temprano","Define primera(datos) que devuelve el primer positivo o None.","","def primera(datos):\n    for v in datos:\n        if v>0:\n            return v\n    return None","primera([-1,0,2,3])==2 and primera([-1,0])==None","return termina la función.","Se prueban presencia y ausencia de coincidencias.")
ex(1,A,2,10,F,"Lambda de unidades","Define decada con lambda.","","decada=lambda tasa:tasa*10","abs(decada(-0.02)+0.2)<1e-10","La expresión va después de dos puntos.","La conversión conserva el signo.")
ex(1,A,3,20,C,"Continue y faltantes","Suma números y cuenta n; usa continue para saltar None.","datos=[14.0,None,14.4,None]","n=0\nsuma=0.0\nfor v in datos:\n    if v==None:\n        continue\n    suma+=v\n    n+=1","n==2 and abs(suma-28.4)<1e-10","Comprueba ausencia antes de sumar.","Los faltantes no son ceros.")
ex(1,A,3,20,W,"Primer cruce con break","Busca anio_cruce, primero sobre 14.3 en P.D, usando break y tolerancia 1e-9.","anio=2000\nanio_cruce=None","for v in serie_anual():\n    if v-14.3>1e-9:\n        anio_cruce=anio\n        break\n    anio+=1","anio_cruce==2016","Actualiza año después de cada vuelta sin cruce.","break evita seguir buscando.")
ex(1,A,3,20,W,"Conversión inversa","Define k_a_c y calcula error_max de ida y vuelta para -15,0,23 °C.","def c_a_k(t):\n    return t+273.15","def k_a_c(t):\n    return t-273.15\nerror_max=0.0\nfor t in [-15,0,23]:\n    error=abs(k_a_c(c_a_k(t))-t)\n    if error>error_max:\n        error_max=error","error_max<1e-10","Deshaz la suma original.","La ida y vuelta verifica coherencia.")
ex(1,A,3,20,W,"Resumen con contrato","Define resumen(datos): devuelve media,conteo; para vacío devuelve None,0.","","def resumen(datos):\n    suma=0.0\n    n=0\n    for v in datos:\n        suma+=v\n        n+=1\n    if n==0:\n        return None,0\n    return suma/n,n","resumen([])==(None,0) and resumen([14,16])==(15,2)","Evita dividir entre cero.","Una serie vacía no tiene media cero.")
ex(1,A,3,25,T,"Comparar tasas impuestas","Con bucles sobre P.D calcula cambio_a y cambio_b entre primer y último valor; tasas 0.02 y -0.01.","a=serie_anual(tasa=0.02)\nb=serie_anual(tasa=-0.01)","primero_a=None\nprimero_b=None\nfor v in a:\n    if primero_a==None:\n        primero_a=v\n    ultimo_a=v\nfor v in b:\n    if primero_b==None:\n        primero_b=v\n    ultimo_b=v\ncambio_a=ultimo_a-primero_a\ncambio_b=ultimo_b-primero_b","abs(cambio_a-0.46)<1e-10 and abs(cambio_b+0.23)<1e-10","Hay 23 intervalos entre 24 años.","Observaciones y duración son distintas.")
ex(1,A,3,25,T,"Integración ampliada P1","Define clasificar(serie,base=14) que devuelve conteos debajo,igual,encima; igualdad con tolerancia 1e-9.","","def clasificar(serie,base=14):\n    debajo=0\n    igual=0\n    encima=0\n    for v in serie:\n        if abs(v-base)<1e-9:\n            igual+=1\n        elif v<base:\n            debajo+=1\n        else:\n            encima+=1\n    return debajo,igual,encima","clasificar(serie_anual(),base=14.2)==(10,1,13)","Resuelve primero la igualdad aproximada.","Las categorías cubren los 24 valores simulados.")

ex(2,N,1,5,P,"Índice final","Obtén resultado con índice negativo.","datos=[14,15,16]","resultado=datos[-1]","resultado==16","-1 cuenta desde el final.","No necesitas calcular la longitud.")
ex(2,N,1,5,P,"Rebanada","Predice datos[1:3]; guarda resultado.","datos=[14,15,16,17]","resultado=datos[1:3]","resultado==[15,16]","El fin queda fuera.","Se seleccionan posiciones 1 y 2.")
ex(2,N,1,5,C,"Copia independiente","Crea copia, cambia su primer valor a 0 y conserva datos.","datos=[14,15]","copia=datos.copy()\ncopia[0]=0","datos==[14,15] and copia==[0,15]","Asignar no copia.","copy separa una lista de escalares.")
ex(2,N,1,5,F,"Clave regional","Consulta Costa en resultado.","regiones={'Costa':[14,15],'Sierra':[12,13]}","resultado=regiones['Costa']","resultado==[14,15]","Usa la clave textual.","La clave tiene significado regional.")
ex(2,N,1,5,F,"Nombres únicos","Cuenta regiones distintas en n.","regiones=['Costa','Costa','Sierra']","n=len(set(regiones))","n==2","set elimina duplicados.","Regiones y filas no son lo mismo.")
ex(2,N,1,5,C,"Espacios del CSV","Limpia espacios y separa campos en resultado.","linea=' Costa,14.0 '","resultado=linea.strip().split(',')","resultado==['Costa','14.0']","strip antes de split.","Este CSV sencillo no tiene campos entrecomillados.")
ex(2,N,2,10,W,"Anomalías por comprensión","Resta 14 a datos simulados con una comprensión en resultado.","datos=[14,15,13]","resultado=[v-14 for v in datos]","resultado==[0,1,-1]","La expresión va antes de for.","Se conserva el orden.")
ex(2,N,2,10,F,"Pares por año","Crea diccionario resultado año→valor; comprueba longitudes.","anios=[2000,2001]\nvalores=[14.0,14.2]","assert len(anios)==len(valores), 'Parejas completas'\nresultado={a:v for a,v in zip(anios,valores)}","resultado=={2000:14.0,2001:14.2}","zip entrega pares.","La comprobación evita truncamiento.")
ex(2,N,2,10,W,"Ordenar tasas","Ordena pares de mayor a menor tasa en resultado; key debe ser una función.","pares=[('Costa',0.2),('Sierra',0.4),('Llanura',-0.1)]","def tasa(par):\n    return par[1]\nresultado=sorted(pares,key=tasa,reverse=True)","resultado[0][0]=='Sierra' and resultado[-1][0]=='Llanura'","reverse=True invierte el orden.","La tasa ocupa la segunda posición.")
ex(2,N,2,10,C,"Método y retorno","Conserva original, crea ordenada con sorted, y retorno con copia.sort().","original=[16,14,15]","ordenada=sorted(original)\ncopia=original.copy()\nretorno=copia.sort()","original==[16,14,15] and ordenada==[14,15,16] and retorno==None and copia==ordenada","sort modifica y devuelve None.","El contrato de cada método debe leerse.")
ex(2,N,2,10,W,"Conversión vigilada","Convierte textos, conserva None donde haya ValueError; guarda resultado.","textos=['14.0','','15.0']","resultado=[]\nfor texto in textos:\n    try:\n        resultado.append(float(texto))\n    except ValueError:\n        resultado.append(None)","resultado==[14.0,None,15.0]","Conserva la posición del faltante.","Saltar un dato desplazaría fechas.")
ex(2,N,2,10,F,"Archivo con contexto","Escribe y lee el CSV simulado en leido con with y UTF-8.","from pathlib import Path\nruta=Path('salida_P2.csv')\ntexto='anio,temp_C\\n2000,14.0\\n'","with open(ruta,'w',encoding='utf-8') as f:\n    f.write(texto)\nwith open(ruta,'r',encoding='utf-8') as f:\n    leido=f.read()","leido==texto and ruta.exists()","w escribe y r lee.","El contexto cierra el recurso.")
ex(2,N,3,25,T,"CSV de P.D con faltantes","Escribe el CSV sencillo de P.D; léelo y crea pares válidos año/temperatura y descartes.","from pathlib import Path\ntexto='anio,temp_C\\n2000,14.0\\n2001,\\n2002,14.4\\n'\nruta=Path('serie_P2.csv')","with open(ruta,'w',encoding='utf-8') as f:\n    f.write(texto)\nwith open(ruta,'r',encoding='utf-8') as f:\n    lineas=f.read().strip().split('\\n')\npares=[]\ndescartes=0\nfor linea in lineas[1:]:\n    anio,valor=linea.split(',')\n    try:\n        pares.append((int(anio),float(valor)))\n    except ValueError:\n        descartes+=1","pares==[(2000,14.0),(2002,14.4)] and descartes==1","No conviertas el vacío a cero.","Cada valor conserva su año.")
ex(2,N,3,25,T,"Integración núcleo P2","Genera P.D para Costa tasa 0.02 y Sierra 0.04; calcula medias y entrega pares ordenados descendentes en resultado.","series={'Costa':serie_anual(tasa=0.02),'Sierra':serie_anual(tasa=0.04)}","medias={r:sum(v)/len(v) for r,v in series.items()}\ndef media(par):\n    return par[1]\nresultado=sorted(medias.items(),key=media,reverse=True)","resultado[0][0]=='Sierra' and abs(medias['Costa']-14.23)<1e-10 and abs(medias['Sierra']-14.46)<1e-10","items entrega clave y valor.","Mayor media no significa siempre mayor tendencia.")
ex(2,A,2,10,P,"Enumerar observaciones","Crea pares posición/valor en resultado.","datos=[14.0,14.2]","resultado=list(enumerate(datos))","resultado==[(0,14.0),(1,14.2)]","list materializa un recorrido.","Posición no equivale a año.")
ex(2,A,2,10,W,"Todas o algunas","Calcula hay_positivos con any y todos_positivos con all.","datos=[-0.1,0.2,0.3]","condiciones=[v>0 for v in datos]\nhay_positivos=any(condiciones)\ntodos_positivos=all(condiciones)","hay_positivos and not todos_positivos","Construye primero booleanos.","any requiere una sola coincidencia.")
ex(2,A,3,20,F,"Leer registros con nombre","Lee .region y .tasa de los dos registros suministrados; guarda ambos pares en resultado. Las fábricas de soporte crean tipos; solo debes leer sus campos.","from collections import namedtuple\nfrom dataclasses import make_dataclass\nRegistro=namedtuple('Registro',['region','tasa'])\nFicha=make_dataclass('Ficha',['region','tasa'])\ntupla_registro=Registro('Costa',0.2)\nclase_registro=Ficha('Sierra',0.4)","resultado=[(tupla_registro.region,tupla_registro.tasa),(clase_registro.region,clase_registro.tasa)]","resultado==[('Costa',0.2),('Sierra',0.4)]","Los campos son atributos.","Se practica lectura, sin escribir clases.")
ex(2,A,3,20,W,"Biblioteca estándar","Guarda tupla resultado con media de [14,16], raíz de 4 y año de date(2000,1,1).","import math\nimport statistics\nfrom datetime import date","resultado=(statistics.mean([14,16]),math.sqrt(4),date(2000,1,1).year)","resultado==(15,2,2000)","Cada módulo agrupa herramientas.","No requiere bibliotecas externas.")
ex(2,A,3,20,W,"Módulo de conversiones","Escribe conversiones_practica.py con decada(t), impórtala y guarda resultado para 0.02.","from pathlib import Path","with open('conversiones_practica.py','w',encoding='utf-8') as f:\n    f.write('def decada(t):\\n    return t * 10\\n')\nfrom conversiones_practica import decada\nresultado=decada(0.02)","abs(resultado-0.2)<1e-10","Ejecuta en el mismo directorio de práctica.","El nombre del archivo sin extensión es el módulo.")
ex(2,A,3,20,C,"Duplicados de años","Conserva el primer par por año en limpios usando un conjunto.","pares=[(2000,14.0),(2000,99.0),(2001,14.2)]","vistos=set()\nlimpios=[]\nfor anio,valor in pares:\n    if anio not in vistos:\n        limpios.append((anio,valor))\n        vistos.add(anio)","limpios==[(2000,14.0),(2001,14.2)]","not in consulta ausencia.","Conservar el primero es la política explícita del ejercicio.")
ex(2,A,3,25,T,"Auditoría regional","Crea auditoria con n,primero,ultimo por región para P.D.","series={'Costa':serie_anual(),'Sierra':serie_anual(n=12,tasa=0.04)}","auditoria={}\nfor r,v in series.items():\n    auditoria[r]={'n':len(v),'primero':v[0],'ultimo':v[-1]}","auditoria['Costa']['n']==24 and auditoria['Sierra']['n']==12 and abs(auditoria['Sierra']['ultimo']-14.44)<1e-10","Anida diccionarios.","Toda comparación necesita cobertura.")
ex(2,A,3,25,T,"Integración ampliada P2","Exporta año,temp_C para serie_anual(n=3), lee de vuelta y reconstruye recuperados.","valores=serie_anual(n=3)","lineas=['anio,temp_C']\nfor i,v in enumerate(valores):\n    lineas.append(f'{2000+i},{v:.2f}')\nwith open('integracion_P2.csv','w',encoding='utf-8') as f:\n    f.write('\\n'.join(lineas)+'\\n')\nwith open('integracion_P2.csv','r',encoding='utf-8') as f:\n    filas=f.read().strip().split('\\n')\nrecuperados=[]\nfor linea in filas[1:]:\n    anio,valor=linea.split(',')\n    recuperados.append(float(valor))","recuperados==[14.0,14.02,14.04]","Conserva encabezado y saltos de línea.","Leer de vuelta comprueba el formato.")

