ex(3,N,1,5,P,"Ejes y elementos","Guarda numero_ejes y elementos.","import numpy as np\na=np.zeros((2,3,4))","numero_ejes=a.ndim\nelementos=a.size","numero_ejes==3 and elementos==24","No confundas ejes y celdas.","2 por 3 por 4 da 24.")
ex(3,N,1,5,F,"Selección por máscara","Selecciona positivos simulados en resultado.",NP+"\na=np.array([-0.2,0,0.3,0.4])","resultado=a[a>0]","np.array_equal(resultado,[0.3,0.4])","La condición crea booleanos.","El cero se excluye.")
ex(3,N,1,5,C,"Copia de fila","Copia primera fila en fila, ponla en ceros y conserva a.",NP+"\na=np.arange(6).reshape(2,3)","fila=a[0].copy()\nfila[:]=0","np.array_equal(a[0],[0,1,2]) and np.array_equal(fila,[0,0,0])","Separa memoria con copy.","Una vista modificaría el arreglo original.")
ex(3,N,1,5,P,"Faltante detectable","Guarda mascara de NaN y n_faltantes.",NP+"\na=np.array([14,np.nan,15])","mascara=np.isnan(a)\nn_faltantes=mascara.sum()","np.array_equal(mascara,[False,True,False]) and n_faltantes==1","Sumar booleanos cuenta verdaderos.","NaN se detecta con isnan.")
ex(3,N,1,5,F,"Diferencias vecinas","Calcula pasos entre datos simulados.",NP+"\na=np.array([14.0,14.2,14.5])","pasos=np.diff(a)","np.allclose(pasos,[0.2,0.3])","Se forman pares vecinos.","Las diferencias no son tasas si cambia el intervalo.")
ex(3,N,2,10,W,"Anomalías por región","Resta base a cada fila con broadcasting en resultado.",NP+"\ndatos=np.array([[14,12,10],[15,13,11]])\nbase=np.array([14,12,10])","resultado=datos-base","np.array_equal(resultado,[[0,0,0],[1,1,1]])","Las tres columnas coinciden.","Cada región conserva su referencia.")
ex(3,N,2,10,C,"Media en el eje correcto","Obtén medias por región sin NaN en resultado; las filas son tiempo.",NP+"\na=np.array([[14,12],[16,np.nan]])","resultado=np.nanmean(a,axis=0)","np.allclose(resultado,[15,12])","Reduce tiempo.","Se conserva un resultado por columna.")
ex(3,N,2,10,F,"Referencia por fila","Resta una base por fila cambiando su forma.",NP+"\na=np.array([[14,15,16],[12,13,14]])\nbase=np.array([14,12])","resultado=a-base.reshape(2,1)","np.array_equal(resultado,[[0,1,2],[0,1,2]])","La dimensión final de base debe ser uno.","La referencia se extiende por columnas.")
ex(3,N,2,10,W,"Línea comunicable","Dibuja y frente a años con label Simulado, eje y Temperatura [°C], título y leyenda; conserva fig,ax.",PL+"\nanios=np.arange(2000,2004)\ny=np.array([14,14.1,14.0,14.2])","fig,ax=plt.subplots()\nax.plot(anios,y,'o-',label='Simulado',color='#0072B2')\nax.set(xlabel='Año',ylabel='Temperatura [°C]',title='Simulado 2000–2003')\nax.legend()","len(ax.lines)==1 and ax.get_ylabel()=='Temperatura [°C]' and ax.get_legend() is not None","Dibuja y rotula sobre ax.","Unidades y origen evitan ambigüedades.")
ex(3,N,2,10,W,"Barras de tasas","Dibuja barras simuladas; eje y Tasa [°C/década].",PL+"\nregiones=['Costa','Sierra']\ntasas=[0.2,0.4]","fig,ax=plt.subplots()\nax.bar(regiones,tasas,color=['#0072B2','#D55E00'])\nax.set(ylabel='Tasa [°C/década]',title='Tasas simuladas')","len(ax.patches)==2 and ax.get_ylabel()=='Tasa [°C/década]'","bar recibe nombres y alturas.","Las barras comparan categorías.")
ex(3,N,2,10,F,"Histograma y dispersión","Crea subplots(1,2); ejes[0] scatter y ejes[1] hist con tres intervalos.",PL+"\nx=np.arange(6)\ny=np.array([0,0.1,-0.1,0.2,0.1,0.3])","fig,ejes=plt.subplots(1,2)\nejes[0].scatter(x,y,color='#0072B2')\nejes[1].hist(y,bins=3,color='#D55E00')\nejes[0].set(xlabel='Paso anual',ylabel='Anomalía [°C]',title='Simulado')\nejes[1].set(xlabel='Anomalía [°C]',ylabel='Conteo',title='Simulado')","len(ejes[0].collections)==1 and len(ejes[1].patches)==3","Cada Axes tiene una posición.","Una vista muestra pares; otra, frecuencias.")
ex(3,N,3,25,T,"Serie P.D vectorizada","Convierte serie_anual, resta su media en anom, calcula pasos con diff y media_anom.",NP+"\na=np.array(serie_anual())","anom=a-a.mean()\npasos=np.diff(a)\nmedia_anom=anom.mean()","anom.shape==(24,) and abs(media_anom)<1e-10 and np.allclose(pasos,0.02)","Una referencia escalar se resta a todos.","Centrar conserva diferencias.")
ex(3,N,3,25,T,"Integración núcleo P3","Dibuja P.D y su tendencia impuesta con dos líneas. Calcula tasa_decada a partir de diferencias; título Simulado.",PL+"\ny=np.array(serie_anual())\nx=np.arange(2000,2024)","tasa_decada=float(np.diff(y).mean()*10)\nfig,ax=plt.subplots()\nax.plot(x,y,'o',label='Serie simulada',color='#0072B2')\nax.plot(x,14+0.02*(x-2000),'--',label='Tasa impuesta',color='#D55E00')\nax.set(xlabel='Año',ylabel='Temperatura [°C]',title='Simulado 2000–2023')\nax.legend()","abs(tasa_decada-0.2)<1e-10 and len(ax.lines)==2 and 'Simulado' in ax.get_title()","La serie anual no tiene ruido.","Se verifica el simulador; aún no es una regresión.")
ex(3,A,2,10,F,"Extremos incluidos","Construye cinco latitudes de -60 a 60.",NP,"lat=np.linspace(-60,60,5)","np.array_equal(lat,[-60,-30,0,30,60])","El tercer argumento es cantidad.","linspace incluye extremos.")
ex(3,A,2,10,C,"Banderas de ausencia","Sustituye -999 por NaN en limpio y calcula media.",NP+"\na=np.array([14,-999,16],dtype=float)","limpio=np.where(a==-999,np.nan,a)\nmedia=np.nanmean(limpio)","media==15 and np.isnan(limpio[1])","La bandera no es temperatura.","Solo se promedian datos válidos.")
ex(3,A,3,20,W,"Ruido repetible","Crea a y b, muestras de 100 valores normales, con generadores distintos iniciados en 2026.",NP,"rng_a=np.random.default_rng(2026)\nrng_b=np.random.default_rng(2026)\na=rng_a.normal(0,0.1,100)\nb=rng_b.normal(0,0.1,100)","np.array_equal(a,b) and a.shape==(100,)","Reinicia la semilla en cada generador.","Dos llamadas seguidas al mismo generador serían diferentes.")
ex(3,A,3,20,W,"Ponderación por latitud","Calcula ponderada con cos(lat) y simple sin pesos. Adelanto de bloque D.",NP+"\nlat=np.array([-60,0,60])\nvalores=np.array([10,20,10])","pesos=np.cos(np.deg2rad(lat))\nponderada=np.average(valores,weights=pesos)\nsimple=valores.mean()","abs(ponderada-15)<1e-10 and ponderada>simple","El ecuador pesa más.","Se asume malla angular regular y cobertura completa.")
ex(3,A,3,20,F,"Mapa divergente","Dibuja tasas con imshow, RdBu_r, límites -0.4,0.4; guarda im y añade colorbar.",PL+"\ntasas=np.array([[-0.4,-0.2],[0.2,0.4]])","fig,ax=plt.subplots()\nim=ax.imshow(tasas,cmap='RdBu_r',vmin=-0.4,vmax=0.4,origin='lower')\nfig.colorbar(im,ax=ax,label='°C/década')\nax.set(title='Tasas simuladas',xlabel='Columna',ylabel='Fila')","im.get_clim()==(-0.4,0.4) and im.get_cmap().name=='RdBu_r'","Centro en cero.","Los colores comparan ambos signos.")
ex(3,A,3,20,W,"Tiempo de vectorización","Mide con perf_counter una resta por comprensión y NumPy; guarda t_lista,t_numpy,b,c. No exijas un ganador.",NP+"\nfrom time import perf_counter\na=np.arange(10000,dtype=float)","inicio=perf_counter()\nb=[v-14 for v in a]\nt_lista=perf_counter()-inicio\ninicio=perf_counter()\nc=a-14\nt_numpy=perf_counter()-inicio","np.allclose(b,c) and t_lista>=0 and t_numpy>=0","El resultado debe ser igual.","El tiempo depende del equipo.")
ex(3,A,3,25,T,"Diferencias con faltantes","En P.D pon NaN en posición 5; calcula diff, n de diferencias faltantes y media válida.",NP+"\na=np.array(serie_anual())\na[5]=np.nan","d=np.diff(a)\nn=np.isnan(d).sum()\nmedia=np.nanmean(d)","n==2 and abs(media-0.02)<1e-10","Una ausencia afecta dos pares.","La propagación depende de la operación.")
ex(3,A,3,25,T,"Integración ampliada P3","Dibuja anomalías de P.D respecto a 14 y su histograma de seis intervalos en dos ejes.",PL+"\ny=np.array(serie_anual())-14\nx=np.arange(2000,2024)","fig,ejes=plt.subplots(1,2)\nejes[0].plot(x,y,'o-',color='#0072B2')\nejes[1].hist(y,bins=6,color='#D55E00')\nejes[0].set(xlabel='Año',ylabel='Anomalía [°C]',title='Simulado')\nejes[1].set(xlabel='Anomalía [°C]',ylabel='Conteo',title='Simulado')","len(ejes[0].lines[0].get_xdata())==24 and len(ejes[1].patches)==6","Usa los mismos valores en ambas vistas.","Los artistas gráficos permiten comprobar los datos.")

ex(4,N,1,5,P,"Anatomía de tabla","Guarda forma y columnas del DataFrame simulado.",PD+"\ndf=pd.DataFrame({'region':['Costa','Sierra'],'temp_C':[14,12]})","forma=df.shape\ncolumnas=list(df.columns)","forma==(2,2) and columnas==['region','temp_C']","shape cuenta filas y columnas.","Los nombres describen variables.")
ex(4,N,1,5,F,"Primera posición","Obtén resultado de la primera posición.",PD+"\ns=pd.Series([14,16],index=[8,9])","resultado=s.iloc[0]","resultado==14","iloc usa posiciones.","El índice puede comenzar en otra etiqueta.")
ex(4,N,1,5,F,"Contar faltantes","Cuenta ausencias en n.",PD+"\ns=pd.Series([14,np.nan,16,np.nan])","n=int(s.isna().sum())","n==2","Suma booleanos.","El conteo documenta cobertura.")
ex(4,N,1,5,C,"Columna derivada","Crea kelvin conservando temp_C.",PD+"\ndf=pd.DataFrame({'temp_C':[0,14]})","df['kelvin']=df['temp_C']+273.15","np.allclose(df['kelvin'],[273.15,287.15]) and df['temp_C'].to_list()==[0,14]","Escribe una columna nueva.","Se conserva el original.")
ex(4,N,1,5,P,"Mes de fecha","Convierte fecha y extrae mes mediante dt.",PD+"\ndf=pd.DataFrame({'fecha':['2000-01-01','2000-07-01']})","df['fecha']=pd.to_datetime(df['fecha'])\nmes=df['fecha'].dt.month","mes.to_list()==[1,7]","dt accede a componentes temporales.","Texto y fecha son tipos diferentes.")
ex(4,N,1,5,F,"Filtrar región","Selecciona Costa con loc en resultado.",PD+"\ndf=pd.DataFrame({'region':['Costa','Sierra','Costa'],'temp_C':[14,12,15]})","resultado=df.loc[df['region']=='Costa'].copy()","len(resultado)==2 and resultado['temp_C'].to_list()==[14,15]","La comparación crea una máscara.","copy separa el resultado.")
ex(4,N,2,10,W,"CSV en memoria","Lee df con StringIO/read_csv; descarta ausencias en limpio.",PD+"\nfrom io import StringIO\ntexto='fecha,temp_C\\n2000-01-01,14\\n2000-02-01,\\n'","df=pd.read_csv(StringIO(texto))\nlimpio=df.dropna(subset=['temp_C'])","len(df)==2 and len(limpio)==1 and limpio.iloc[0]['temp_C']==14","El campo vacío se detecta automáticamente.","No depende de archivos externos.")
ex(4,N,2,10,F,"Índice temporal","Convierte fecha, usa set_index y sort_index; guarda Series s.",PD+"\ndf=pd.DataFrame({'fecha':['2000-02-01','2000-01-01'],'temp_C':[15,14]})","df['fecha']=pd.to_datetime(df['fecha'])\ns=df.set_index('fecha').sort_index()['temp_C']","s.iloc[0]==14 and s.index.is_monotonic_increasing","La propiedad is_monotonic_increasing comprueba orden.","Ordenar fechas garantiza el recorrido temporal.")
ex(4,N,2,10,W,"Doce referencias","Calcula clima agrupando el mes del índice.",PD+"\ns=pd.Series(np.arange(24,dtype=float),index=pd.date_range('2000-01-01',periods=24,freq='MS'))","clima=s.groupby(s.index.month).mean()","len(clima)==12 and clima.loc[1]==6 and clima.loc[12]==17","Enero reúne posiciones 0 y 12.","Cada mes tiene su propia referencia.")
ex(4,N,2,10,F,"Anomalías alineadas","Calcula anom con map de clima a cada mes.",PD+"\ns=pd.Series(np.arange(24,dtype=float),index=pd.date_range('2000-01-01',periods=24,freq='MS'))\nclima=s.groupby(s.index.month).mean()","anom=s-s.index.month.map(clima).to_numpy()","np.allclose(anom.iloc[:12],-6) and np.allclose(anom.iloc[12:],6)","No restes índices incompatibles.","La referencia se coloca por posición temporal.")
ex(4,N,2,10,C,"Cobertura anual","Calcula medias YE y conserva solo años con doce valores.",PD+"\ns=pd.Series(np.arange(24,dtype=float),index=pd.date_range('2000-01-01',periods=24,freq='MS'))\ns.iloc[15]=np.nan","conteo=s.resample('YE').count()\nanual=s.resample('YE').mean().where(conteo==12)","anual.notna().sum()==1 and pd.isna(anual.iloc[1]) and anual.iloc[0]==5.5","count excluye ausencias.","La media incompleta queda marcada.")
ex(4,N,2,10,W,"Resumen por región","Construye resumen con media y n mediante agg.",PD+"\ndf=pd.DataFrame({'region':['Costa','Costa','Sierra'],'temp_C':[14,16,12]})","resumen=df.groupby('region').agg(media=('temp_C','mean'),n=('temp_C','count'))","resumen.loc['Costa','media']==15 and resumen.loc['Costa','n']==2","Nombra resultados al agregar.","La cobertura acompaña a la media.")
ex(4,N,3,25,T,"Anomalías anuales P.D","Genera P.D, elige Costa y base 2000–2009; calcula clima,anom,anual. Exige doce meses.",PD+"\ndf=serie_mensual()\ns=df.loc[df['region']=='Costa'].set_index('fecha')['temp_C']","base=s.loc['2000':'2009']\nclima=base.groupby(base.index.month).mean()\nanom=s-s.index.month.map(clima).to_numpy()\nanual=anom.resample('YE').mean().where(anom.resample('YE').count()==12)","len(anual)==24 and anual.notna().sum()==24 and abs(anom.loc['2000':'2009'].mean())<1e-10","Recorta antes de agrupar.","En la base completa las anomalías promedian cero.")
ex(4,N,3,25,T,"Integración núcleo P4","Resume P.D por región con media,n; une meta, ordena descendente y exporta sin índice.",PD+"\ndf=serie_mensual()\nmeta=pd.DataFrame({'region':['Costa','Sierra','Llanura'],'origen':['simulado']*3})","resumen=df.groupby('region').agg(media=('temp_C','mean'),n=('temp_C','count')).reset_index()\nresultado=resumen.merge(meta,on='region',validate='many_to_one').sort_values('media',ascending=False)\nresultado.to_csv('resumen_P4.csv',index=False)","len(resultado)==3 and (resultado['n']==288).all() and resultado.iloc[0]['region']=='Sierra'","reset_index convierte la clave en columna.","Se entrega magnitud, cobertura y procedencia.")
ex(4,A,2,10,P,"Ventana móvil","Calcula rolling de tres valores en resultado.",PD+"\ns=pd.Series([1.0,2.0,3.0,4.0])","resultado=s.rolling(3,min_periods=3).mean()","resultado.isna().sum()==2 and resultado.iloc[-1]==3","Los dos primeros pasos no tienen tres observaciones.","Suavizar no añade información.")
ex(4,A,2,10,F,"Apilar regiones","Concatena a,b con índice nuevo en resultado.",PD+"\na=pd.DataFrame({'region':['Costa'],'temp_C':[14]})\nb=pd.DataFrame({'region':['Sierra'],'temp_C':[12]})","resultado=pd.concat([a,b],ignore_index=True)","resultado.index.to_list()==[0,1] and len(resultado)==2","concat apila filas por defecto.","Se evitan etiquetas duplicadas.")
ex(4,A,3,20,W,"Tabla año por región","Construye pivot con promedio explícito.",PD+"\ndf=pd.DataFrame({'anio':[2000,2000,2001,2001],'region':['Costa','Sierra']*2,'temp_C':[14,12,15,13]})","pivot=df.pivot_table(index='anio',columns='region',values='temp_C',aggfunc='mean')","pivot.shape==(2,2) and pivot.loc[2001,'Costa']==15","Año en filas, región en columnas.","La agregación define duplicados.")
ex(4,A,3,20,C,"Unión sin pérdidas","Une por la izquierda con validate; cuenta n_sin_meta.",PD+"\ntasas=pd.DataFrame({'region':['Costa','Sierra'],'tasa':[0.2,0.4]})\nmeta=pd.DataFrame({'region':['Costa'],'unidad':['°C/década']})","unido=tasas.merge(meta,on='region',how='left',validate='many_to_one')\nn_sin_meta=int(unido['unidad'].isna().sum())","len(unido)==2 and n_sin_meta==1","Una unión interna perdería Sierra.","Los metadatos ausentes deben verse.")
ex(4,A,3,20,W,"Días a meses","Simula 31 días a 14 °C y calcula mensual y conteo con ME. np.full crea valores constantes; D significa día.",PD,"s=pd.Series(np.full(31,14.0),index=pd.date_range('2000-01-01',periods=31,freq='D'))\nmensual=s.resample('ME').mean()\nconteo=s.resample('ME').count()","len(mensual)==1 and mensual.iloc[0]==14 and conteo.iloc[0]==31","La frecuencia de entrada es diaria.","La cobertura debe adaptarse al calendario.")
ex(4,A,3,20,C,"Relleno exploratorio","Solo para explorar una gráfica: rellena ausencias con media regional en exploracion; conserva df. transform devuelve un resumen por fila.",PD+"\ndf=pd.DataFrame({'region':['Costa','Costa','Sierra','Sierra'],'temp_C':[14,np.nan,12,np.nan]})","medias=df.groupby('region')['temp_C'].transform('mean')\nexploracion=df.copy()\nexploracion['temp_C']=exploracion['temp_C'].fillna(medias)","df['temp_C'].isna().sum()==2 and exploracion['temp_C'].to_list()==[14,14,12,12]","transform conserva longitud.","Este relleno no se usa en la tendencia del proyecto.")
ex(4,A,3,25,T,"Cobertura de P.D","Genera P.D con faltantes y agrega total,validos; añade faltantes. size incluye vacíos; count los excluye.",PD+"\ndf=serie_mensual(faltantes=True)","cobertura=df.groupby('region').agg(total=('temp_C','size'),validos=('temp_C','count'))\ncobertura['faltantes']=cobertura['total']-cobertura['validos']","(cobertura['total']==288).all() and (cobertura['faltantes']==3).all()","Resta conteos.","El simulador coloca tres ausencias por región después de la base.")
ex(4,A,3,25,T,"Integración ampliada P4","Construye tabla anual media,n_meses de Costa con P.D faltante. Enmascara años incompletos y exporta con índice temporal. rename cambia nombres de columnas.",PD+"\ndf=serie_mensual(faltantes=True)\ns=df.loc[df['region']=='Costa'].set_index('fecha')['temp_C']","base=s.loc['2000':'2009']\nclima=base.groupby(base.index.month).mean()\nanom=s-s.index.month.map(clima).to_numpy()\nresultado=anom.resample('YE').agg(['mean','count'])\nresultado=resultado.rename(columns={'mean':'media','count':'n_meses'})\nresultado['media']=resultado['media'].where(resultado['n_meses']==12)\nresultado.to_csv('cobertura_anual_P4.csv',index=True)","len(resultado)==24 and resultado['media'].notna().sum()==21 and (resultado['n_meses']==11).sum()==3","Conserva los conteos además de medias.","Tres años tienen once meses.")

ex(5,N,1,5,P,"Leer una pendiente","Ajusta datos simulados y guarda decada.",SP+"\nx=np.arange(5)\ny=14+0.02*x","r=linregress(x,y)\ndecada=10*r.slope","abs(decada-0.2)<1e-10","slope tiene unidades por año.","La conversión no depende del intercepto.")
ex(5,N,1,5,F,"Selección cercana","Elige celda lat=2,lon=-88 con nearest en malla de P.D.","ds=malla()","celda=ds['temp'].sel(lat=2,lon=-88,method='nearest')","float(celda.lat)==0 and float(celda.lon)==-90 and celda.sizes['time']==24","Busca las coordenadas disponibles.","nearest no interpola.")
ex(5,N,2,10,C,"Años reales al ajustar","Falta 2002: ajusta con años, no posiciones; guarda r.",SP+"\nx=np.array([2000,2001,2003,2004])\ny=14+0.02*(x-2000)","r=linregress(x-2000,y)","abs(r.slope-0.02)<1e-10 and abs(r.intercept-14)<1e-10","Traslada el origen sin comprimir huecos.","Se conservan unidades por año.")
ex(5,N,2,10,W,"Contrato reproducible","Define tasa_decada(x,y) con máscara común; raise si faltan tres pares o años distintos.",SP,"def tasa_decada(x,y):\n    x=np.array(x,dtype=float)\n    y=np.array(y,dtype=float)\n    ok=np.isfinite(x)&np.isfinite(y)\n    if ok.sum()<3 or np.min(x[ok])==np.max(x[ok]):\n        raise ValueError('Se necesitan tres pares y años distintos')\n    return 10*linregress(x[ok],y[ok]).slope","abs(tasa_decada([2000,2001,2002,2003],[14,14.02,np.nan,14.06])-0.2)<1e-10","Filtra ambos arreglos juntos.","La validación precede al ajuste.")
ex(5,N,3,15,T,"Integración núcleo P5","Con malla P.D calcula mapa medio temporal y serie regional lat -30 a 0; escribe NetCDF y lee copia con load.","import xarray as xr\nds=malla()","mapa=ds['temp'].mean('time')\nserie=ds['temp'].sel(lat=slice(-30,0)).mean(['lat','lon'])\nds.to_netcdf('integracion_P5.nc',engine='netcdf4')\nwith xr.open_dataset('integracion_P5.nc',engine='netcdf4') as lectura:\n    copia=lectura.load()","mapa.shape==(3,4) and serie.shape==(24,) and copia.identical(ds)","identical compara valores, coordenadas y atributos.","Leer de vuelta verifica significado.")
ex(5,A,3,20,W,"Resultados estadísticos ampliados","Con P.D anual lee Mann-Kendall y OLS. Guarda tasa_mk,tasa_ols por década y texto_resumen. Los pasos son años regulares.",SP+"\nimport pymannkendall as mk\nimport statsmodels.api as sm\ny=np.array(serie_anual())\nx=np.arange(len(y))","r_mk=mk.original_test(y)\nr_ols=sm.OLS(y,sm.add_constant(x)).fit()\ntasa_mk=10*r_mk.slope\ntasa_ols=10*r_ols.params[1]\ntexto_resumen=r_ols.summary().as_text()","abs(tasa_mk-0.2)<1e-8 and abs(tasa_ols-0.2)<1e-8 and 'OLS Regression Results' in texto_resumen","El coeficiente 1 corresponde a x tras añadir constante.","Una señal impuesta verifica APIs, no supuestos físicos.")
ex(5,A,3,20,W,"xarray ponderado y anual","Promedia malla con pesos cos(lat), luego resample YE; conserva serie,anual.",NP+"\nds=malla()","pesos=np.cos(np.deg2rad(ds.lat))\nserie=ds['temp'].weighted(pesos).mean(('lat','lon'))\nanual=serie.resample(time='YE').mean()","serie.sizes['time']==24 and anual.sizes['time']==2 and bool(serie.notnull().all())","Los pesos se alinean con lat.","El área de celdas reales requiere revisar geometría.")
ex(5,A,3,20,T,"Integración ampliada P5","Escribe test_conversion.py con test_decada que compruebe la conversión 0.02→0.2; mide una resta vectorizada de P.D en duracion. Ejecuta pytest en la terminal de práctica.",NP+"\nfrom pathlib import Path\nfrom time import perf_counter","codigo='def test_decada():\\n    assert abs(0.02 * 10 - 0.2) < 1e-10\\n'\nwith open('test_conversion.py','w',encoding='utf-8') as f:\n    f.write(codigo)\na=np.array(serie_anual())\ninicio=perf_counter()\nanom=a-14\nduracion=perf_counter()-inicio","Path('test_conversion.py').exists() and duracion>=0 and np.allclose(anom,np.arange(24)*0.02)","pytest descubre funciones test_.","La prueba expresa un contrato y el cronómetro no altera resultados.")
